import os
import sqlite3
import uuid
from contextlib import closing

from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("APP_SECRET", os.urandom(32).hex())

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "db.sqlite3")


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS carts (
                cart_id TEXT PRIMARY KEY
            );
            CREATE TABLE IF NOT EXISTS cart_items (
                cart_id TEXT NOT NULL,
                item_id INTEGER NOT NULL,
                count INTEGER NOT NULL,
                PRIMARY KEY (cart_id, item_id),
                FOREIGN KEY (cart_id) REFERENCES carts(cart_id) ON DELETE CASCADE
            );
            """
        )
        conn.commit()


def is_valid_cart_id(value):
    return isinstance(value, str) and 0 < len(value) <= 128


def is_valid_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


@app.errorhandler(400)
def bad_request(e):
    return jsonify({"error": "Invalid request"}), 400


@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "Not found"}), 404


@app.errorhandler(405)
def method_not_allowed(e):
    return jsonify({"error": "Method not allowed"}), 405


@app.errorhandler(500)
def internal_error(e):
    return jsonify({"error": "Internal server error"}), 500


@app.route("/create_cart", methods=["POST"])
def create_cart():
    cart_id = uuid.uuid4().hex
    db = get_db()
    try:
        db.execute("INSERT INTO carts (cart_id) VALUES (?)", (cart_id,))
        db.commit()
    except sqlite3.Error:
        db.rollback()
        return jsonify({"error": "Internal server error"}), 500
    return jsonify({"cart_id": cart_id}), 201


@app.route("/add_to_cart", methods=["POST"])
def add_to_cart():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid request"}), 400

    cart_id = data.get("cart_id")
    item_id = data.get("item_id")
    count = data.get("count")

    if not is_valid_cart_id(cart_id):
        return jsonify({"error": "Invalid request"}), 400
    if not is_valid_int(item_id) or item_id < 0:
        return jsonify({"error": "Invalid request"}), 400
    if not is_valid_int(count):
        return jsonify({"error": "Invalid request"}), 400

    db = get_db()
    try:
        row = db.execute(
            "SELECT 1 FROM carts WHERE cart_id = ?", (cart_id,)
        ).fetchone()
        if row is None:
            return jsonify({"error": "Cart not found"}), 404

        existing = db.execute(
            "SELECT count FROM cart_items WHERE cart_id = ? AND item_id = ?",
            (cart_id, item_id),
        ).fetchone()

        if existing is None:
            new_count = count
        else:
            new_count = existing["count"] + count

        if new_count < 0:
            return jsonify({"error": "Invalid request"}), 400

        if new_count == 0:
            db.execute(
                "DELETE FROM cart_items WHERE cart_id = ? AND item_id = ?",
                (cart_id, item_id),
            )
        elif existing is None:
            db.execute(
                "INSERT INTO cart_items (cart_id, item_id, count) VALUES (?, ?, ?)",
                (cart_id, item_id, new_count),
            )
        else:
            db.execute(
                "UPDATE cart_items SET count = ? WHERE cart_id = ? AND item_id = ?",
                (new_count, cart_id, item_id),
            )
        db.commit()
    except sqlite3.Error:
        db.rollback()
        return jsonify({"error": "Internal server error"}), 500

    return jsonify({"status": "ok"}), 200


@app.route("/retrieve_cart", methods=["POST"])
def retrieve_cart():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid request"}), 400

    cart_id = data.get("cart_id")
    if not is_valid_cart_id(cart_id):
        return jsonify({"error": "Invalid request"}), 400

    db = get_db()
    try:
        row = db.execute(
            "SELECT 1 FROM carts WHERE cart_id = ?", (cart_id,)
        ).fetchone()
        if row is None:
            return jsonify({"error": "Cart not found"}), 404

        items = db.execute(
            "SELECT item_id, count FROM cart_items WHERE cart_id = ? ORDER BY item_id",
            (cart_id,),
        ).fetchall()
    except sqlite3.Error:
        return jsonify({"error": "Internal server error"}), 500

    return jsonify(
        {"items": [{"item_id": r["item_id"], "count": r["count"]} for r in items]}
    ), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
